import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { normalizeFixture } from "../tooling/fixture-oracle/src/normalize.mjs";

const root = process.cwd();
const outputDirectory = process.argv[2];
if (!outputDirectory) throw new Error("usage: node scripts/collect-stage0-evidence.mjs <output-directory>");
const output = path.resolve(outputDirectory);
const logs = path.join(output, "logs");
await mkdir(logs, { recursive: true });

const checks = [];
const commands = [
  command("pnpm-offline-install", "corepack", ["pnpm", "install", "--frozen-lockfile", "--offline"]),
  command("node-contracts", "corepack", ["pnpm", "stage0:check"]),
  command("gradle-contracts", process.platform === "win32" ? path.join(root, "gradlew.bat") : "./gradlew", ["stage0Check", "--offline"]),
];

for (const check of commands) {
  const startedAt = new Date().toISOString();
  const result = spawnSync(check.command, check.args, { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  const combined = redact(`${result.stdout ?? ""}${result.stderr ?? ""}`);
  const logPath = path.join(logs, `${check.id}.log`);
  await writeFile(logPath, combined);
  const record = {
    id: check.id,
    command: safeCommand(check),
    startedAt,
    completedAt: new Date().toISOString(),
    exitCode: result.status ?? 1,
    status: result.status === 0 ? "passed" : "failed",
    log: path.relative(output, logPath).split(path.sep).join("/"),
    logSha256: sha256(combined),
  };
  checks.push(record);
  await writeFile(path.join(output, "verification-log.ndjson"), `${checks.map((item) => JSON.stringify(item)).join("\n")}\n`);
  if (result.status !== 0) {
    await writeManifest("failed");
    throw new Error(`${check.id} failed with exit code ${record.exitCode}`);
  }
}

const fixtureManifest = JSON.parse(await readFile(path.join(root, "contracts/fixtures/manifest.json"), "utf8"));
const fixtureProjections = [];
for (const item of fixtureManifest.fixtures) {
  fixtureProjections.push(await normalizeFixture(path.join(root, "contracts/fixtures", item.path)));
}
const protocolTrace = {
  schemaVersion: "2.0",
  traceType: "ji-pi-projection-v1",
  sourceRevision: fixtureManifest.sourceRevision,
  fixtures: fixtureProjections,
};
const traceText = `${JSON.stringify(protocolTrace, null, 2)}\n`;
await writeFile(path.join(output, "protocol-trace.json"), traceText);
await writeManifest("passed");
await writeFile(path.join(output, "summary.md"), [
  "# Stage 0 verification",
  "",
  "All offline Stage 0 gates passed. The checked-in generators were reproducible, the TypeScript oracle and independent Java runner matched all five pinned Pi fixture domains, ACP structural classifications were complete, public module and naming rules passed, and Java/Node contract tests passed.",
  "",
  "No real provider, credential, `.env`, network service, container, or browser was used.",
  "",
].join("\n"));
process.stdout.write(`Stage 0 evidence written to ${output}\n`);

async function writeManifest(status) {
  const tracePath = path.join(output, "protocol-trace.json");
  let traceSha256 = null;
  try {
    traceSha256 = sha256(await readFile(tracePath));
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
  const manifest = {
    schemaVersion: "1.0",
    stage: 0,
    status,
    generatedAt: new Date().toISOString(),
    environment: {
      java: firstLine(runVersion("java", ["-version"])),
      node: runVersion("node", ["--version"]).trim(),
      pnpm: runVersion("corepack", ["pnpm", "--version"]).trim(),
      gradle: "8.14.3",
    },
    source: {
      fixtureManifest: "contracts/fixtures/manifest.json",
      piRevision: fixtureManifest.sourceRevision,
      piFixtureDomains: fixtureManifest.fixtures.map((fixture) => fixture.domain),
    },
    checks,
    artifacts: {
      structuredLog: "verification-log.ndjson",
      protocolTrace: traceSha256 === null ? null : { path: "protocol-trace.json", sha256: traceSha256 },
    },
    constraints: {
      offline: true,
      realProviderUsed: false,
      secretsRead: false,
    },
  };
  await writeFile(path.join(output, "verification-manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
}

function command(id, executable, args) {
  if (process.platform === "win32" && (executable === "corepack" || executable.endsWith(".bat"))) {
    return { id, command: "cmd.exe", args: ["/d", "/s", "/c", executable, ...args] };
  }
  return { id, command: executable, args };
}

function runVersion(executable, args) {
  const invocation = command("version", executable, args);
  const result = spawnSync(invocation.command, invocation.args, { cwd: root, encoding: "utf8" });
  if (result.status !== 0) throw result.error ?? new Error(`${executable} version command failed`);
  return `${result.stdout ?? ""}${result.stderr ?? ""}`;
}

function firstLine(value) {
  return value.split(/\r?\n/, 1)[0];
}

function safeCommand(check) {
  if (check.id === "gradle-contracts") return "./gradlew stage0Check --offline";
  return [check.command, ...check.args].join(" ");
}

function redact(value) {
  const withoutWorkspace = value.split(root).join("<workspace>");
  return withoutWorkspace.replace(/((?:api[_-]?key|authorization|bearer|secret|password)\s*(?:[=:]\s*|\s+))[^\s"']+/gi, "$1<redacted>");
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

